import app from './worker-v137.js';
import { COMPANY_NETWORK_SCHEMA_V138 } from './company-network-schema-v138.js';

const HEADERS={'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'};
const PRODUCT_STATUSES=new Set(['DRAFT','ACTIVE','ARCHIVED']);
const CONDITIONS=new Set(['NEW','REFURBISHED']);
const POLICY_TYPES=new Set(['WARRANTY','RETURN','SUPPORT']);
const REQUEST_TYPES=new Set(['SUPPORT','WARRANTY','RETURN']);
const REQUEST_STATUSES=new Set(['OPEN','IN_PROGRESS','WAITING','RESOLVED','REJECTED','CANCELLED']);
const SEVERITIES=new Set(['INFO','IMPORTANT','SAFETY']);
const now=()=>new Date().toISOString();
const uid=p=>`${p}${crypto.randomUUID().replaceAll('-','')}`;
const publicId=p=>`${p}-${crypto.randomUUID().replaceAll('-','').slice(0,16).toUpperCase()}`;
const clean=(v,n=5000)=>String(v??'').replace(/\0/g,'').trim().slice(0,n);
const json=(v,s=200,h={})=>new Response(JSON.stringify(v),{status:s,headers:{...HEADERS,...h}});
const safeJson=(v,f={})=>{try{return JSON.parse(v||'')}catch{return f}};
const int=(v,min,max)=>{const x=Number(v);return Number.isInteger(x)&&x>=min&&x<=max?x:null};
const cents=v=>int(v,0,1_000_000_000);
const currency=v=>/^[A-Z]{3}$/.test(clean(v,3).toUpperCase())?clean(v,3).toUpperCase():'EUR';
const bool=v=>v===true||v===1||v==='1';
const normalized=v=>clean(v,500).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();
const safeUrl=v=>{try{const u=new URL(clean(v,1000));return u.protocol==='https:'?u.href:null}catch{return null}};
function log(event,fields={}){console.log(JSON.stringify({scope:'still_company_network',event,at:now(),...fields}))}
async function sha(v){const d=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(v)));return[...new Uint8Array(d)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function cookie(request,name){for(const part of(request.headers.get('cookie')||'').split(';')){const[k,...v]=part.trim().split('=');if(k===name)return decodeURIComponent(v.join('='))}return''}
async function buyerSession(request,env){const token=cookie(request,'still_buyer');if(!token)return null;return env.DB.prepare(`SELECT a.id buyer_account_id,a.email,a.name FROM buyer_sessions s JOIN buyer_accounts a ON a.id=s.buyer_account_id WHERE s.token_hash=? AND s.expires_at>? AND a.status='active'`).bind(await sha(token),now()).first()}
async function companySession(request,env){const token=cookie(request,'still_company');if(!token)return null;return env.DB.prepare(`SELECT m.id member_id,m.email,m.role,o.id organization_id,o.name organization_name,o.status organization_status,o.country_code,o.website_url,o.support_email FROM merchant_sessions s JOIN merchant_members m ON m.id=s.member_id JOIN merchant_organizations o ON o.id=m.organization_id WHERE s.token_hash=? AND s.expires_at>? AND m.status='active'`).bind(await sha(token),now()).first()}
const canWrite=c=>c&&['owner','admin','manager'].includes(c.role);
function sameOrigin(request){const origin=request.headers.get('origin');return!origin||origin===new URL(request.url).origin}
function rewrite(request,pathname){const u=new URL(request.url);u.pathname=pathname;u.search='';return new Request(u,{method:'GET',headers:request.headers})}

let schemaReady;
async function ensureSchema(env){if(!schemaReady){const inventory=[
  `CREATE TABLE IF NOT EXISTS inventory_locations(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,organization_id TEXT NOT NULL,name TEXT NOT NULL,code TEXT NOT NULL,address TEXT,status TEXT NOT NULL DEFAULT 'active',created_by_member_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(organization_id,code))`,
  `CREATE TABLE IF NOT EXISTS inventory_items(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,organization_id TEXT NOT NULL,sku TEXT NOT NULL,name TEXT NOT NULL,barcode TEXT,unit TEXT NOT NULL DEFAULT 'unit',reorder_point INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,created_by_member_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(organization_id,sku))`,
  `CREATE TABLE IF NOT EXISTS inventory_balances(organization_id TEXT NOT NULL,item_id TEXT NOT NULL,location_id TEXT NOT NULL,on_hand INTEGER NOT NULL DEFAULT 0,reserved INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL,PRIMARY KEY(organization_id,item_id,location_id))`,
  `CREATE TABLE IF NOT EXISTS inventory_movements(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,organization_id TEXT NOT NULL,item_id TEXT NOT NULL,location_id TEXT NOT NULL,quantity_delta INTEGER NOT NULL,reserved_delta INTEGER NOT NULL DEFAULT 0,reason TEXT NOT NULL,reference_type TEXT,reference_id TEXT,created_by_member_id TEXT NOT NULL,created_at TEXT NOT NULL)`
];schemaReady=env.DB.batch([...inventory,...COMPANY_NETWORK_SCHEMA_V138].map(sql=>env.DB.prepare(sql))).catch(error=>{schemaReady=undefined;throw error})}await schemaReady}
function eventStatement(env,{organizationId=null,buyerId=null,entityType,entityId=null,eventType,details={}}){log(eventType,{organizationId,buyerId,entityType,entityId});return env.DB.prepare(`INSERT INTO company_network_events(id,public_id,organization_id,buyer_account_id,entity_type,entity_public_id,event_type,details_json,created_at) VALUES(?,?,?,?,?,?,?,?,?)`).bind(uid('cne_'),publicId('CNE'),organizationId,buyerId,entityType,entityId,eventType,JSON.stringify(details).slice(0,4000),now())}
function historyStatement(env,buyerId,entityType,entityId,eventType,title,details={},sourceId=null){return env.DB.prepare(`INSERT INTO world_history_events(id,public_id,buyer_account_id,entity_type,entity_public_id,event_type,title,details_json,source_type,source_public_id,occurred_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)`).bind(uid('whe_'),publicId('HIS'),buyerId,entityType,entityId,eventType,title,JSON.stringify(details).slice(0,4000),'company_network',sourceId,now(),now())}

async function profile(request,env,company){if(request.method==='GET'){const row=await env.DB.prepare(`SELECT p.*,o.status organization_status FROM company_network_public_profiles p JOIN merchant_organizations o ON o.id=p.organization_id WHERE p.organization_id=?`).bind(company.organization_id).first();const plan=await env.DB.prepare(`SELECT * FROM company_network_plan_config WHERE plan_key='BUSINESS_STANDARD'`).first();return json({profile:row||null,verificationStatus:company.organization_status,plan:{key:plan.plan_key,name:plan.display_name,monthlyPriceCents:plan.monthly_price_cents,currency:plan.currency,billingAvailable:!!plan.billing_available,subscriptionStatus:'NOT_CONFIGURED'}})}if(!canWrite(company))return json({error:'forbidden'},403);const body=await request.json().catch(()=>null);if(!body)return json({error:'invalid_json'},400);const display=clean(body.displayName||company.organization_name,140),description=clean(body.description,1600),email=clean(body.supportEmail||company.support_email,254),website=body.websiteUrl?safeUrl(body.websiteUrl):null,publish=bool(body.published);if(display.length<2)return json({error:'display_name_required'},422);if(publish&&company.organization_status!=='verified')return json({error:'company_verification_required'},409);const ts=now();await env.DB.prepare(`INSERT INTO company_network_public_profiles(organization_id,display_name,description,support_email,website_url,country_code,published,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(organization_id) DO UPDATE SET display_name=excluded.display_name,description=excluded.description,support_email=excluded.support_email,website_url=excluded.website_url,published=excluded.published,updated_at=excluded.updated_at`).bind(company.organization_id,display,description||null,email||null,website,company.country_code||'hr',publish?1:0,ts,ts).run();return json({ok:true,published:publish})}

function productJson(row){return{publicId:row.public_id,name:row.name,brand:row.brand||null,model:row.model||null,category:row.category||null,description:row.description||null,gtin:row.gtin||null,manufacturerPartNumber:row.manufacturer_part_number||null,specifications:safeJson(row.specifications_json,{}),provenance:safeJson(row.provenance_json,{}),status:row.status,createdAt:row.created_at,updatedAt:row.updated_at}}
async function products(request,env,company){if(request.method==='GET'){const rows=await env.DB.prepare(`SELECT * FROM company_network_products WHERE organization_id=? ORDER BY updated_at DESC LIMIT 200`).bind(company.organization_id).all();return json({products:(rows.results||[]).map(productJson)})}if(!canWrite(company))return json({error:'forbidden'},403);const body=await request.json().catch(()=>null),name=clean(body?.name,180),status=clean(body?.status||'DRAFT',20).toUpperCase();if(name.length<2||!PRODUCT_STATUSES.has(status))return json({error:'invalid_product'},422);if(status==='ACTIVE'&&company.organization_status!=='verified')return json({error:'company_verification_required'},409);const gtin=clean(body.gtin,30)||null;if(gtin){const duplicate=await env.DB.prepare(`SELECT public_id FROM company_network_products WHERE organization_id=? AND gtin=?`).bind(company.organization_id,gtin).first();if(duplicate)return json({error:'gtin_exists',productId:duplicate.public_id},409)}const id=uid('cnp_'),pid=publicId('PRD'),ts=now();await env.DB.batch([env.DB.prepare(`INSERT INTO company_network_products(id,public_id,organization_id,name,brand,model,category,description,gtin,manufacturer_part_number,specifications_json,provenance_json,status,created_by_member_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,pid,company.organization_id,name,clean(body.brand,120)||null,clean(body.model,120)||null,clean(body.category,120)||null,clean(body.description,3000)||null,gtin,clean(body.manufacturerPartNumber,120)||null,JSON.stringify(body.specifications&&typeof body.specifications==='object'?body.specifications:{}).slice(0,8000),JSON.stringify({source:'COMPANY_DECLARED',memberId:company.member_id,recordedAt:ts}),status,company.member_id,ts,ts),eventStatement(env,{organizationId:company.organization_id,entityType:'product',entityId:pid,eventType:'product_created'})]);return json({ok:true,productId:pid,status},201)}
async function productForCompany(env,company,id){return env.DB.prepare(`SELECT * FROM company_network_products WHERE organization_id=? AND public_id=?`).bind(company.organization_id,id).first()}
async function addVariant(request,env,company,product){if(!canWrite(company))return json({error:'forbidden'},403);const body=await request.json().catch(()=>null),name=clean(body?.name,140),sku=clean(body?.sku,100)||null;if(name.length<2)return json({error:'variant_name_required'},422);const ts=now(),pid=publicId('VAR');try{await env.DB.prepare(`INSERT INTO company_network_variants(id,public_id,product_id,organization_id,name,sku,gtin,attributes_json,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?, 'ACTIVE',?,?)`).bind(uid('cnv_'),pid,product.id,company.organization_id,name,sku,clean(body.gtin,30)||null,JSON.stringify(body.attributes&&typeof body.attributes==='object'?body.attributes:{}).slice(0,4000),ts,ts).run()}catch{return json({error:'variant_identifier_exists'},409)}return json({ok:true,variantId:pid},201)}
async function policies(request,env,company){if(request.method==='GET'){const r=await env.DB.prepare(`SELECT * FROM company_network_policies WHERE organization_id=? ORDER BY active DESC,updated_at DESC`).bind(company.organization_id).all();return json({policies:r.results||[]})}if(!canWrite(company))return json({error:'forbidden'},403);const b=await request.json().catch(()=>null),type=clean(b?.type,20).toUpperCase(),name=clean(b?.name,140),summary=clean(b?.summary,3000),days=b?.durationDays===null||b?.durationDays===undefined?null:int(b.durationDays,0,36500),url=b?.termsUrl?safeUrl(b.termsUrl):null;if(!POLICY_TYPES.has(type)||name.length<2||summary.length<2||(b?.termsUrl&&!url))return json({error:'invalid_policy'},422);const pid=publicId('POL'),ts=now();await env.DB.prepare(`INSERT INTO company_network_policies(id,public_id,organization_id,policy_type,name,summary,duration_days,terms_url,active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,1,?,?)`).bind(uid('cnl_'),pid,company.organization_id,type,name,summary,days,url,ts,ts).run();return json({ok:true,policyId:pid},201)}

async function inventoryRef(env,company,itemPid,locationPid){return env.DB.prepare(`SELECT i.id item_id,i.public_id item_public_id,i.name item_name,l.id location_id,l.public_id location_public_id,l.name location_name,b.on_hand,b.reserved FROM inventory_items i JOIN inventory_locations l ON l.organization_id=i.organization_id JOIN inventory_balances b ON b.organization_id=i.organization_id AND b.item_id=i.id AND b.location_id=l.id WHERE i.organization_id=? AND i.public_id=? AND l.public_id=? AND i.active=1 AND l.status='active'`).bind(company.organization_id,itemPid,locationPid).first()}
async function offers(request,env,company){if(request.method==='GET'){const r=await env.DB.prepare(`SELECT f.*,p.public_id product_public_id,p.name product_name,p.brand,p.model,v.public_id variant_public_id,v.name variant_name,i.public_id inventory_item_public_id,l.public_id inventory_location_public_id,COALESCE(b.on_hand-b.reserved,0) available FROM company_network_offers f JOIN company_network_products p ON p.id=f.product_id LEFT JOIN company_network_variants v ON v.id=f.variant_id LEFT JOIN inventory_items i ON i.id=f.inventory_item_id LEFT JOIN inventory_locations l ON l.id=f.inventory_location_id LEFT JOIN inventory_balances b ON b.organization_id=f.organization_id AND b.item_id=f.inventory_item_id AND b.location_id=f.inventory_location_id WHERE f.organization_id=? ORDER BY f.active DESC,f.updated_at DESC`).bind(company.organization_id).all();return json({offers:r.results||[]})}if(!canWrite(company))return json({error:'forbidden'},403);if(company.organization_status!=='verified')return json({error:'company_verification_required'},409);const b=await request.json().catch(()=>null),product=await productForCompany(env,company,clean(b?.productId,50));if(!product||product.status!=='ACTIVE')return json({error:'active_product_required'},422);let variant=null;if(b.variantId){variant=await env.DB.prepare(`SELECT * FROM company_network_variants WHERE organization_id=? AND product_id=? AND public_id=? AND status='ACTIVE'`).bind(company.organization_id,product.id,clean(b.variantId,50)).first();if(!variant)return json({error:'variant_not_found'},404)}const inv=await inventoryRef(env,company,clean(b.inventoryItemId,50),clean(b.inventoryLocationId,50));if(!inv)return json({error:'inventory_balance_required'},422);const condition=clean(b.condition,20).toUpperCase(),price=cents(b.priceCents),checkout=clean(b.checkoutMode||'EXTERNAL',30).toUpperCase(),external=b.externalCheckoutUrl?safeUrl(b.externalCheckoutUrl):null;if(!CONDITIONS.has(condition)||price===null||!['EXTERNAL','STILL_PROVIDER'].includes(checkout))return json({error:'invalid_offer'},422);if(checkout==='EXTERNAL'&&!external)return json({error:'external_checkout_url_required'},422);if(checkout==='STILL_PROVIDER'&&!env.STRIPE_SECRET_KEY)return json({error:'still_payment_provider_not_configured'},409);const warranty=b.warrantyPolicyId?await env.DB.prepare(`SELECT id FROM company_network_policies WHERE organization_id=? AND public_id=? AND policy_type='WARRANTY' AND active=1`).bind(company.organization_id,b.warrantyPolicyId).first():null,returns=b.returnPolicyId?await env.DB.prepare(`SELECT id FROM company_network_policies WHERE organization_id=? AND public_id=? AND policy_type='RETURN' AND active=1`).bind(company.organization_id,b.returnPolicyId).first():null;if(b.warrantyPolicyId&&!warranty||b.returnPolicyId&&!returns)return json({error:'policy_not_found'},404);const pid=publicId('OFR'),ts=now();try{await env.DB.batch([env.DB.prepare(`INSERT INTO company_network_offers(id,public_id,organization_id,product_id,variant_id,inventory_item_id,inventory_location_id,condition,price_cents,currency,checkout_mode,external_checkout_url,warranty_policy_id,return_policy_id,active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,1,?,?)`).bind(uid('cno_'),pid,company.organization_id,product.id,variant?.id||null,inv.item_id,inv.location_id,condition,price,currency(b.currency),checkout,external,warranty?.id||null,returns?.id||null,ts,ts),eventStatement(env,{organizationId:company.organization_id,entityType:'offer',entityId:pid,eventType:'offer_published',details:{inventoryItemId:inv.item_public_id,locationId:inv.location_public_id}})])}catch{return json({error:'offer_exists'},409)}return json({ok:true,offerId:pid,available:Math.max(0,inv.on_hand-inv.reserved)},201)}

function offerProjection(row){return{publicId:row.public_id,product:{publicId:row.product_public_id,name:row.product_name,brand:row.brand||null,model:row.model||null,category:row.category||null,description:row.description||null,gtin:row.gtin||null},variant:row.variant_public_id?{publicId:row.variant_public_id,name:row.variant_name}:null,company:{id:row.organization_id,name:row.company_name,verified:row.organization_status==='verified'},condition:row.condition,priceCents:row.price_cents,currency:row.currency,available:Math.max(0,Number(row.available||0)),checkout:{mode:row.checkout_mode,externalUrl:row.checkout_mode==='EXTERNAL'?row.external_checkout_url:null},warranty:row.warranty_name?{name:row.warranty_name,summary:row.warranty_summary,durationDays:row.warranty_days}:null,returns:row.return_name?{name:row.return_name,summary:row.return_summary,durationDays:row.return_days}:null}}
async function publicOffers(env,{query='',limit=60}={}){const term=`%${normalized(query)}%`;const r=await env.DB.prepare(`SELECT f.*,p.public_id product_public_id,p.name product_name,p.brand,p.model,p.category,p.description,p.gtin,v.public_id variant_public_id,v.name variant_name,o.name company_name,o.status organization_status,COALESCE(b.on_hand-b.reserved,0) available,wp.name warranty_name,wp.summary warranty_summary,wp.duration_days warranty_days,rp.name return_name,rp.summary return_summary,rp.duration_days return_days FROM company_network_offers f JOIN company_network_products p ON p.id=f.product_id JOIN merchant_organizations o ON o.id=f.organization_id JOIN company_network_public_profiles pp ON pp.organization_id=o.id LEFT JOIN company_network_variants v ON v.id=f.variant_id LEFT JOIN inventory_balances b ON b.organization_id=f.organization_id AND b.item_id=f.inventory_item_id AND b.location_id=f.inventory_location_id LEFT JOIN company_network_policies wp ON wp.id=f.warranty_policy_id LEFT JOIN company_network_policies rp ON rp.id=f.return_policy_id WHERE f.active=1 AND p.status='ACTIVE' AND o.status='verified' AND pp.published=1 AND COALESCE(b.on_hand-b.reserved,0)>0 AND (?='%%' OR LOWER(p.name||' '||COALESCE(p.brand,'')||' '||COALESCE(p.model,'')||' '||COALESCE(p.category,'')) LIKE ?) ORDER BY f.price_cents ASC,p.name ASC LIMIT ?`).bind(term,term,int(limit,1,100)||60).all();return(r.results||[]).map(offerProjection)}
function matchScore(offer,need){const hay=normalized(`${offer.product.name} ${offer.product.brand||''} ${offer.product.model||''} ${offer.product.category||''}`),tokens=[...new Set(normalized(`${need.title||''} ${need.category||''} ${(need.desiredAttributes||[]).join(' ')}`).split(' ').filter(x=>x.length>2))];let score=0;const reasons=[];for(const token of tokens)if(hay.includes(token))score+=4;if(need.category&&normalized(offer.product.category)===normalized(need.category)){score+=20;reasons.push('CATEGORY_MATCH')}if(need.conditionPreference&&offer.condition===clean(need.conditionPreference,20).toUpperCase()){score+=8;reasons.push('CONDITION_MATCH')}if(need.budgetMaxCents&&offer.priceCents<=need.budgetMaxCents){score+=6;reasons.push('WITHIN_BUDGET')}if(tokens.some(t=>hay.includes(t)))reasons.push('PRODUCT_TERMS_MATCH');return{score,reasons}}
async function commerceOptions(env,need){const offers=await publicOffers(env,{limit:100}),ranked=offers.map(offer=>({...offer,match:matchScore(offer,need)})).filter(x=>x.match.score>0).sort((a,b)=>b.match.score-a.match.score||a.priceCents-b.priceCents||a.publicId.localeCompare(b.publicId));return ranked.slice(0,20)}

async function releaseExpired(env){const expired=await env.DB.prepare(`SELECT oi.inventory_item_id,oi.inventory_location_id,oi.quantity,o.organization_id,o.public_id FROM company_network_orders o JOIN company_network_order_items oi ON oi.order_id=o.id WHERE o.status IN ('INTENT','AWAITING_EXTERNAL_CONFIRMATION') AND o.reservation_expires_at<? AND oi.inventory_item_id IS NOT NULL`).bind(now()).all();for(const row of expired.results||[])await env.DB.batch([env.DB.prepare(`UPDATE inventory_balances SET reserved=MAX(0,reserved-?),updated_at=? WHERE organization_id=? AND item_id=? AND location_id=?`).bind(row.quantity,now(),row.organization_id,row.inventory_item_id,row.inventory_location_id),env.DB.prepare(`UPDATE company_network_orders SET status='EXPIRED',updated_at=? WHERE public_id=? AND status IN ('INTENT','AWAITING_EXTERNAL_CONFIRMATION')`).bind(now(),row.public_id)]);return(expired.results||[]).length}
async function createOrder(request,env,buyer){await releaseExpired(env);const b=await request.json().catch(()=>null),quantity=int(b?.quantity??1,1,100);if(!b||quantity===null)return json({error:'invalid_order'},422);const offer=await env.DB.prepare(`SELECT f.*,p.name product_name,p.public_id product_public_id,o.status organization_status,pp.published,COALESCE(b.on_hand-b.reserved,0) available FROM company_network_offers f JOIN company_network_products p ON p.id=f.product_id JOIN merchant_organizations o ON o.id=f.organization_id JOIN company_network_public_profiles pp ON pp.organization_id=o.id LEFT JOIN inventory_balances b ON b.organization_id=f.organization_id AND b.item_id=f.inventory_item_id AND b.location_id=f.inventory_location_id WHERE f.public_id=? AND f.active=1 AND p.status='ACTIVE'`).bind(clean(b.offerId,60)).first();if(!offer||offer.organization_status!=='verified'||!offer.published)return json({error:'offer_not_available'},404);if(Number(offer.available)<quantity)return json({error:'insufficient_inventory'},409);if(offer.checkout_mode==='STILL_PROVIDER'&&!env.STRIPE_SECRET_KEY)return json({error:'still_payment_provider_not_configured'},409);const ts=now(),expires=new Date(Date.now()+30*60*1000).toISOString(),orderId=uid('cno_'),orderPid=publicId('ORD'),itemPid=publicId('ORI'),status=offer.checkout_mode==='EXTERNAL'?'AWAITING_EXTERNAL_CONFIRMATION':'INTENT';const reserved=await env.DB.prepare(`UPDATE inventory_balances SET reserved=reserved+?,updated_at=? WHERE organization_id=? AND item_id=? AND location_id=? AND on_hand-reserved>=? RETURNING reserved,on_hand`).bind(quantity,ts,offer.organization_id,offer.inventory_item_id,offer.inventory_location_id,quantity).first();if(!reserved)return json({error:'insufficient_inventory'},409);try{await env.DB.batch([env.DB.prepare(`INSERT INTO company_network_orders(id,public_id,buyer_account_id,organization_id,status,payment_mode,payment_status,external_checkout_url,total_cents,currency,reservation_expires_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?, ?,?,?,?,?,?)`).bind(orderId,orderPid,buyer.buyer_account_id,offer.organization_id,status,offer.checkout_mode,offer.checkout_mode==='EXTERNAL'?'NOT_RECORDED':'PENDING',offer.external_checkout_url,offer.price_cents*quantity,offer.currency,expires,ts,ts),env.DB.prepare(`INSERT INTO company_network_order_items(id,public_id,order_id,offer_id,product_id,variant_id,inventory_item_id,inventory_location_id,quantity,unit_price_cents,currency,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)`).bind(uid('cni_'),itemPid,orderId,offer.id,offer.product_id,offer.variant_id,offer.inventory_item_id,offer.inventory_location_id,quantity,offer.price_cents,offer.currency,ts),env.DB.prepare(`INSERT INTO inventory_movements(id,public_id,organization_id,item_id,location_id,quantity_delta,reserved_delta,reason,reference_type,reference_id,created_by_member_id,created_at) VALUES(?,?,?,?,?,0,?,'commerce_reservation','company_network_order',?,'system',?)`).bind(uid('inm_'),publicId('MOV'),offer.organization_id,offer.inventory_item_id,offer.inventory_location_id,quantity,orderPid,ts),eventStatement(env,{organizationId:offer.organization_id,buyerId:buyer.buyer_account_id,entityType:'order',entityId:orderPid,eventType:'order_intent_created',details:{offerId:offer.public_id,quantity}})])}catch(error){await env.DB.prepare(`UPDATE inventory_balances SET reserved=MAX(0,reserved-?),updated_at=? WHERE organization_id=? AND item_id=? AND location_id=?`).bind(quantity,now(),offer.organization_id,offer.inventory_item_id,offer.inventory_location_id).run();throw error}return json({ok:true,order:{publicId:orderPid,status,paymentMode:offer.checkout_mode,paymentStatus:offer.checkout_mode==='EXTERNAL'?'NOT_RECORDED':'PENDING',totalCents:offer.price_cents*quantity,currency:offer.currency,reservationExpiresAt:expires},nextAction:offer.checkout_mode==='EXTERNAL'?{type:'BUY_FROM_COMPANY',url:offer.external_checkout_url}:null},201)}

async function orderForCompany(env,company,id){return env.DB.prepare(`SELECT o.*,oi.id order_item_id,oi.public_id order_item_public_id,oi.product_id,oi.variant_id,oi.inventory_item_id,oi.inventory_location_id,oi.quantity,oi.unit_price_cents,oi.thing_passport_id,p.public_id product_public_id,p.name product_name,p.brand,p.model,p.gtin FROM company_network_orders o JOIN company_network_order_items oi ON oi.order_id=o.id JOIN company_network_products p ON p.id=oi.product_id WHERE o.organization_id=? AND o.public_id=?`).bind(company.organization_id,id).first()}
async function createThingFromOrder(env,row){if(row.thing_passport_id)return env.DB.prepare(`SELECT public_id FROM ownership_passports WHERE id=?`).bind(row.thing_passport_id).first();const ts=now(),thingId=uid('opp_'),thingPid=publicId('STP');await env.DB.batch([env.DB.prepare(`INSERT INTO ownership_passports(id,public_id,buyer_account_id,organization_id,created_by,kind,title,business_name,reference,purchased_on,status,created_at,updated_at) SELECT ?,?,?,?,'company','product',?,name,?,date(?),'connected',?,? FROM merchant_organizations WHERE id=?`).bind(thingId,thingPid,row.buyer_account_id,row.organization_id,row.product_name,row.public_id,row.confirmed_at||ts,ts,ts,row.organization_id),env.DB.prepare(`INSERT INTO world_thing_profiles(passport_id,buyer_account_id,thing_type,category,manufacturer,model,serial_number,gtin,purchase_price_cents,currency,lifecycle_state,source,review_status,created_at,updated_at) VALUES(?,?,'product',NULL,?,?,?,?,?,?,'OWNED','still_purchase','CONFIRMED',?,?)`).bind(thingId,row.buyer_account_id,row.brand||null,row.model||null,null,row.gtin||null,row.unit_price_cents*row.quantity,row.currency,ts,ts),env.DB.prepare(`UPDATE company_network_order_items SET thing_passport_id=? WHERE id=?`).bind(thingId,row.order_item_id),env.DB.prepare(`INSERT INTO company_network_relationships(id,public_id,buyer_account_id,organization_id,thing_passport_id,source_type,support_access,warranty_access,service_history_access,product_update_access,created_at,updated_at) VALUES(?,?,?,?,?,'ORDER',1,1,0,1,?,?)`).bind(uid('cnr_'),publicId('REL'),row.buyer_account_id,row.organization_id,thingId,ts,ts),historyStatement(env,row.buyer_account_id,'thing',thingPid,'thing.purchased','Purchase confirmed',{orderId:row.public_id,productId:row.product_public_id,companyId:row.organization_id},row.public_id),eventStatement(env,{organizationId:row.organization_id,buyerId:row.buyer_account_id,entityType:'thing',entityId:thingPid,eventType:'order_thing_created',details:{orderId:row.public_id}})]);return{public_id:thingPid}}
async function confirmOrder(request,env,company,id){if(!canWrite(company))return json({error:'forbidden'},403);const row=await orderForCompany(env,company,id);if(!row)return json({error:'order_not_found'},404);if(!['INTENT','AWAITING_EXTERNAL_CONFIRMATION'].includes(row.status))return json({error:'order_not_confirmable',status:row.status},409);if(row.reservation_expires_at<now())return json({error:'reservation_expired'},409);const b=await request.json().catch(()=>null),reference=clean(b?.paymentReference,180);if(row.payment_mode==='EXTERNAL'&&reference.length<3)return json({error:'external_payment_reference_required'},422);if(row.payment_mode==='STILL_PROVIDER')return json({error:'provider_webhook_confirmation_required'},409);const ts=now();const changed=await env.DB.prepare(`UPDATE inventory_balances SET on_hand=on_hand-?,reserved=reserved-?,updated_at=? WHERE organization_id=? AND item_id=? AND location_id=? AND on_hand>=? AND reserved>=? RETURNING on_hand,reserved`).bind(row.quantity,row.quantity,ts,row.organization_id,row.inventory_item_id,row.inventory_location_id,row.quantity,row.quantity).first();if(!changed)return json({error:'inventory_reservation_invalid'},409);await env.DB.batch([env.DB.prepare(`UPDATE company_network_orders SET status='CONFIRMED',payment_status='CONFIRMED',payment_reference=?,confirmed_at=?,updated_at=? WHERE id=?`).bind(reference,ts,ts,row.id),env.DB.prepare(`INSERT INTO inventory_movements(id,public_id,organization_id,item_id,location_id,quantity_delta,reserved_delta,reason,reference_type,reference_id,created_by_member_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)`).bind(uid('inm_'),publicId('MOV'),row.organization_id,row.inventory_item_id,row.inventory_location_id,-row.quantity,-row.quantity,'confirmed_sale','company_network_order',row.public_id,company.member_id,ts),eventStatement(env,{organizationId:row.organization_id,buyerId:row.buyer_account_id,entityType:'order',entityId:row.public_id,eventType:'external_payment_confirmed',details:{reference}})]);row.confirmed_at=ts;const thing=await createThingFromOrder(env,row);return json({ok:true,status:'CONFIRMED',paymentStatus:'CONFIRMED',thingId:thing.public_id})}
async function listOrders(env,buyer,company){if(buyer){const r=await env.DB.prepare(`SELECT o.public_id,o.status,o.payment_mode,o.payment_status,o.total_cents,o.currency,o.external_checkout_url,o.reservation_expires_at,o.confirmed_at,o.created_at,org.name company_name,p.name product_name,oi.quantity,op.public_id thing_public_id FROM company_network_orders o JOIN merchant_organizations org ON org.id=o.organization_id JOIN company_network_order_items oi ON oi.order_id=o.id JOIN company_network_products p ON p.id=oi.product_id LEFT JOIN ownership_passports op ON op.id=oi.thing_passport_id WHERE o.buyer_account_id=? ORDER BY o.created_at DESC LIMIT 100`).bind(buyer.buyer_account_id).all();return json({orders:r.results||[]})}const r=await env.DB.prepare(`SELECT o.public_id,o.status,o.payment_mode,o.payment_status,o.total_cents,o.currency,o.payment_reference,o.reservation_expires_at,o.confirmed_at,o.created_at,p.name product_name,oi.quantity FROM company_network_orders o JOIN company_network_order_items oi ON oi.order_id=o.id JOIN company_network_products p ON p.id=oi.product_id WHERE o.organization_id=? ORDER BY o.created_at DESC LIMIT 200`).bind(company.organization_id).all();return json({orders:r.results||[]})}

function randomToken(){const bytes=new Uint8Array(32);crypto.getRandomValues(bytes);return[...bytes].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function createClaim(request,env,company){if(!canWrite(company))return json({error:'forbidden'},403);const b=await request.json().catch(()=>null),product=await productForCompany(env,company,clean(b?.productId,60));if(!product)return json({error:'product_not_found'},404);let variant=null;if(b.variantId){variant=await env.DB.prepare(`SELECT id FROM company_network_variants WHERE organization_id=? AND product_id=? AND public_id=?`).bind(company.organization_id,product.id,clean(b.variantId,60)).first();if(!variant)return json({error:'variant_not_found'},404)}let orderItem=null;if(b.orderItemId){orderItem=await env.DB.prepare(`SELECT oi.id FROM company_network_order_items oi JOIN company_network_orders o ON o.id=oi.order_id WHERE o.organization_id=? AND o.status='CONFIRMED' AND oi.public_id=? AND oi.product_id=?`).bind(company.organization_id,clean(b.orderItemId,60),product.id).first();if(!orderItem)return json({error:'confirmed_order_item_required'},409)}const token=randomToken(),ts=now(),expires=new Date(Date.now()+(int(b.expiresInDays,1,365)||30)*86400000).toISOString(),notice='The token is shown once. Still stores only its SHA-256 hash.';await env.DB.prepare(`INSERT INTO company_network_claim_tokens(id,token_hash,organization_id,product_id,variant_id,order_item_id,serial_number,expires_at,created_by_member_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)`).bind(uid('cnt_'),await sha(token),company.organization_id,product.id,variant?.id||null,orderItem?.id||null,clean(b.serialNumber,180)||null,expires,company.member_id,ts).run();return json({ok:true,claim:{token,expiresAt:expires,qrUrl:`${new URL(request.url).origin}/claim#${token}`,notice}},201)}
async function resolveClaim(request,env){const b=await request.json().catch(()=>null),token=clean(b?.token,128);if(!/^[a-f0-9]{64}$/.test(token))return json({error:'invalid_claim_token'},422);const row=await env.DB.prepare(`SELECT t.id,t.expires_at,t.claimed_at,t.serial_number,p.public_id product_public_id,p.name,p.brand,p.model,p.category,p.description,p.gtin,v.public_id variant_public_id,v.name variant_name,o.name company_name,o.status organization_status FROM company_network_claim_tokens t JOIN company_network_products p ON p.id=t.product_id JOIN merchant_organizations o ON o.id=t.organization_id LEFT JOIN company_network_variants v ON v.id=t.variant_id WHERE t.token_hash=?`).bind(await sha(token)).first();if(!row||row.expires_at<now())return json({error:'claim_not_found'},404);if(row.claimed_at)return json({error:'claim_already_used'},409);return json({claim:{product:{publicId:row.product_public_id,name:row.name,brand:row.brand||null,model:row.model||null,category:row.category||null,description:row.description||null,gtin:row.gtin||null},variant:row.variant_public_id?{publicId:row.variant_public_id,name:row.variant_name}:null,company:{name:row.company_name,verified:row.organization_status==='verified'},serialNumber:row.serial_number||null,expiresAt:row.expires_at}})}
async function claimProduct(request,env,buyer){const b=await request.json().catch(()=>null),token=clean(b?.token,128);if(!/^[a-f0-9]{64}$/.test(token))return json({error:'invalid_claim_token'},422);const row=await env.DB.prepare(`SELECT t.*,p.public_id product_public_id,p.name,p.brand,p.model,p.category,p.gtin,o.name company_name,o.status organization_status FROM company_network_claim_tokens t JOIN company_network_products p ON p.id=t.product_id JOIN merchant_organizations o ON o.id=t.organization_id WHERE t.token_hash=?`).bind(await sha(token)).first();if(!row||row.expires_at<now())return json({error:'claim_not_found'},404);if(row.claimed_at)return json({error:'claim_already_used'},409);const duplicate=await env.DB.prepare(`SELECT op.public_id,op.title,tp.serial_number,tp.gtin FROM ownership_passports op JOIN world_thing_profiles tp ON tp.passport_id=op.id WHERE op.buyer_account_id=? AND op.status<>'archived' AND ((? IS NOT NULL AND tp.serial_number=?) OR (? IS NOT NULL AND tp.gtin=?)) LIMIT 1`).bind(buyer.buyer_account_id,row.serial_number,row.serial_number,row.gtin,row.gtin).first();if(duplicate&&!b.existingThingId&&!bool(b.confirmCreate))return json({error:'possible_duplicate',existingThing:{publicId:duplicate.public_id,title:duplicate.title,serialNumber:duplicate.serial_number,gtin:duplicate.gtin}},409);let thing;if(b.existingThingId){thing=await env.DB.prepare(`SELECT id,public_id FROM ownership_passports WHERE buyer_account_id=? AND public_id=? AND status<>'archived'`).bind(buyer.buyer_account_id,clean(b.existingThingId,60)).first();if(!thing)return json({error:'thing_not_found'},404)}else{const ts=now();thing={id:uid('opp_'),public_id:publicId('STP')};await env.DB.batch([env.DB.prepare(`INSERT INTO ownership_passports(id,public_id,buyer_account_id,organization_id,created_by,kind,title,business_name,status,created_at,updated_at) VALUES(?,?,?,?,'company','product',?,?,'connected',?,?)`).bind(thing.id,thing.public_id,buyer.buyer_account_id,row.organization_id,row.name,row.company_name,ts,ts),env.DB.prepare(`INSERT INTO world_thing_profiles(passport_id,buyer_account_id,thing_type,category,manufacturer,model,serial_number,gtin,lifecycle_state,source,review_status,created_at,updated_at) VALUES(?,?,'product',?,?,?,?,?,'OWNED','company_qr_claim','CONFIRMED',?,?)`).bind(thing.id,buyer.buyer_account_id,row.category||null,row.brand||null,row.model||null,row.serial_number||null,row.gtin||null,ts,ts)])}const ts=now(),claimed=await env.DB.prepare(`UPDATE company_network_claim_tokens SET claimed_by_buyer_account_id=?,claimed_thing_passport_id=?,claimed_at=? WHERE id=? AND claimed_at IS NULL AND expires_at>? RETURNING id`).bind(buyer.buyer_account_id,thing.id,ts,row.id,ts).first();if(!claimed)return json({error:'claim_already_used'},409);await env.DB.batch([env.DB.prepare(`INSERT INTO company_network_relationships(id,public_id,buyer_account_id,organization_id,thing_passport_id,source_type,support_access,warranty_access,service_history_access,product_update_access,created_at,updated_at) VALUES(?,?,?,?,?,'QR_CLAIM',1,1,0,1,?,?) ON CONFLICT(buyer_account_id,organization_id,thing_passport_id) DO UPDATE SET revoked_at=NULL,updated_at=excluded.updated_at`).bind(uid('cnr_'),publicId('REL'),buyer.buyer_account_id,row.organization_id,thing.id,ts,ts),historyStatement(env,buyer.buyer_account_id,'thing',thing.public_id,'thing.company_claimed','Verified product identity added',{productId:row.product_public_id,companyId:row.organization_id},row.product_public_id),eventStatement(env,{organizationId:row.organization_id,buyerId:buyer.buyer_account_id,entityType:'thing',entityId:thing.public_id,eventType:'product_claimed'})]);return json({ok:true,thingId:thing.public_id,linkedExisting:!!b.existingThingId})}

async function relationships(request,env,buyer){if(request.method==='GET'){const r=await env.DB.prepare(`SELECT r.public_id,r.support_access,r.warranty_access,r.service_history_access,r.product_update_access,r.revoked_at,r.created_at,r.updated_at,o.name company_name,p.public_id thing_public_id,p.title thing_title,COALESCE(m.granted,0) marketing_consent FROM company_network_relationships r JOIN merchant_organizations o ON o.id=r.organization_id JOIN ownership_passports p ON p.id=r.thing_passport_id LEFT JOIN company_network_marketing_consents m ON m.buyer_account_id=r.buyer_account_id AND m.organization_id=r.organization_id WHERE r.buyer_account_id=? ORDER BY r.updated_at DESC`).bind(buyer.buyer_account_id).all();return json({relationships:r.results||[]})}const b=await request.json().catch(()=>null),row=await env.DB.prepare(`SELECT * FROM company_network_relationships WHERE buyer_account_id=? AND public_id=?`).bind(buyer.buyer_account_id,clean(b?.relationshipId,60)).first();if(!row)return json({error:'relationship_not_found'},404);const ts=now();await env.DB.batch([env.DB.prepare(`UPDATE company_network_relationships SET support_access=?,warranty_access=?,service_history_access=?,product_update_access=?,revoked_at=?,updated_at=? WHERE id=?`).bind(bool(b.supportAccess)?1:0,bool(b.warrantyAccess)?1:0,bool(b.serviceHistoryAccess)?1:0,bool(b.productUpdateAccess)?1:0,bool(b.revoked)?ts:null,ts,row.id),env.DB.prepare(`INSERT INTO company_network_marketing_consents(buyer_account_id,organization_id,granted,source,updated_at) VALUES(?,?,?,'BUYER_SETTINGS',?) ON CONFLICT(buyer_account_id,organization_id) DO UPDATE SET granted=excluded.granted,source=excluded.source,updated_at=excluded.updated_at`).bind(buyer.buyer_account_id,row.organization_id,bool(b.marketingConsent)?1:0,ts)]);return json({ok:true})}
async function supportRequests(request,env,buyer,company){if(request.method==='GET'){if(company){const r=await env.DB.prepare(`SELECT s.public_id,s.request_type,s.subject,s.description,s.status,s.company_note,s.created_at,s.updated_at,p.public_id thing_public_id,p.title thing_title FROM company_network_support_requests s JOIN company_network_relationships rel ON rel.buyer_account_id=s.buyer_account_id AND rel.organization_id=s.organization_id AND rel.thing_passport_id=s.thing_passport_id JOIN ownership_passports p ON p.id=s.thing_passport_id WHERE s.organization_id=? AND rel.revoked_at IS NULL AND ((s.request_type='SUPPORT' AND rel.support_access=1) OR (s.request_type IN ('WARRANTY','RETURN') AND rel.warranty_access=1)) ORDER BY s.updated_at DESC LIMIT 200`).bind(company.organization_id).all();return json({requests:r.results||[]})}const r=await env.DB.prepare(`SELECT s.public_id,s.request_type,s.subject,s.description,s.status,s.company_note,s.created_at,s.updated_at,o.name company_name,p.public_id thing_public_id,p.title thing_title FROM company_network_support_requests s JOIN merchant_organizations o ON o.id=s.organization_id JOIN ownership_passports p ON p.id=s.thing_passport_id WHERE s.buyer_account_id=? ORDER BY s.updated_at DESC LIMIT 100`).bind(buyer.buyer_account_id).all();return json({requests:r.results||[]})}const b=await request.json().catch(()=>null);if(buyer){const rel=await env.DB.prepare(`SELECT r.* FROM company_network_relationships r JOIN ownership_passports p ON p.id=r.thing_passport_id WHERE r.buyer_account_id=? AND p.public_id=? AND r.revoked_at IS NULL`).bind(buyer.buyer_account_id,clean(b?.thingId,60)).first(),type=clean(b?.type,20).toUpperCase(),subject=clean(b?.subject,180),description=clean(b?.description,4000);if(!rel||!REQUEST_TYPES.has(type)||subject.length<2||description.length<2)return json({error:'invalid_support_request'},422);if(type==='SUPPORT'&&!rel.support_access||type!=='SUPPORT'&&!rel.warranty_access)return json({error:'sharing_permission_required'},403);const pid=publicId('REQ'),ts=now();await env.DB.batch([env.DB.prepare(`INSERT INTO company_network_support_requests(id,public_id,buyer_account_id,organization_id,thing_passport_id,request_type,subject,description,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?, 'OPEN',?,?)`).bind(uid('cns_'),pid,buyer.buyer_account_id,rel.organization_id,rel.thing_passport_id,type,subject,description,ts,ts),eventStatement(env,{organizationId:rel.organization_id,buyerId:buyer.buyer_account_id,entityType:'support_request',entityId:pid,eventType:'support_request_created',details:{type}})]);return json({ok:true,requestId:pid},201)}if(!canWrite(company))return json({error:'forbidden'},403);const typeStatus=clean(b?.status,30).toUpperCase(),row=await env.DB.prepare(`SELECT * FROM company_network_support_requests WHERE organization_id=? AND public_id=?`).bind(company.organization_id,clean(b?.requestId,60)).first();if(!row||!REQUEST_STATUSES.has(typeStatus))return json({error:'invalid_support_update'},422);await env.DB.prepare(`UPDATE company_network_support_requests SET status=?,company_note=?,updated_at=? WHERE id=?`).bind(typeStatus,clean(b.companyNote,4000)||null,now(),row.id).run();return json({ok:true,status:typeStatus})}
async function notices(request,env,company){if(request.method==='GET'){const r=await env.DB.prepare(`SELECT n.public_id,n.title,n.body,n.severity,n.published_at,n.created_at,p.public_id product_public_id,p.name product_name FROM company_network_notices n JOIN company_network_products p ON p.id=n.product_id WHERE n.organization_id=? ORDER BY n.created_at DESC LIMIT 200`).bind(company.organization_id).all();return json({notices:r.results||[]})}if(!canWrite(company))return json({error:'forbidden'},403);const b=await request.json().catch(()=>null),product=await productForCompany(env,company,clean(b?.productId,60)),title=clean(b?.title,180),body=clean(b?.body,5000),severity=clean(b?.severity||'INFO',20).toUpperCase(),publish=bool(b?.publish);if(!product||title.length<2||body.length<2||!SEVERITIES.has(severity))return json({error:'invalid_notice'},422);if(publish&&company.organization_status!=='verified')return json({error:'company_verification_required'},409);const pid=publicId('NTC'),ts=now();await env.DB.prepare(`INSERT INTO company_network_notices(id,public_id,organization_id,product_id,title,body,severity,published_at,created_by_member_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)`).bind(uid('cnn_'),pid,company.organization_id,product.id,title,body,severity,publish?ts:null,company.member_id,ts,ts).run();return json({ok:true,noticeId:pid,published:publish},201)}

async function compareWithMine(env,buyer,offerId){const offer=(await publicOffers(env,{limit:100})).find(x=>x.publicId===offerId);if(!offer)return json({error:'offer_not_found'},404);const rows=await env.DB.prepare(`SELECT p.public_id,p.title,tp.manufacturer,tp.model,tp.gtin,tp.lifecycle_state FROM ownership_passports p JOIN world_thing_profiles tp ON tp.passport_id=p.id WHERE p.buyer_account_id=? AND p.status<>'archived' ORDER BY p.updated_at DESC LIMIT 300`).bind(buyer.buyer_account_id).all();const mine=(rows.results||[]).map(x=>{let score=0,reasons=[];if(x.gtin&&offer.product.gtin&&x.gtin===offer.product.gtin){score+=100;reasons.push('SAME_GTIN')}if(normalized(x.manufacturer)===normalized(offer.product.brand)&&x.manufacturer){score+=20;reasons.push('SAME_BRAND')}if(normalized(x.model)===normalized(offer.product.model)&&x.model){score+=40;reasons.push('SAME_MODEL')}return{thingId:x.public_id,title:x.title,lifecycleState:x.lifecycle_state,score,reasons}}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score||a.thingId.localeCompare(b.thingId));return json({offer,ownedMatches:mine,recommendation:mine[0]?.score>=60?'KEEP_OR_COMPARE_FIRST':'NO_EQUIVALENT_OWNED_THING_FOUND',explanation:mine.length?'Still found a related thing you already own. Compare before buying.':'No equivalent owned Thing was found from confirmed identifiers.'})}
async function prePurchasePassport(env,buyer,offerId){const offer=(await publicOffers(env,{limit:100})).find(x=>x.publicId===offerId);if(!offer)return json({error:'offer_not_found'},404);return json({passport:{state:'PRE_PURCHASE',product:offer.product,variant:offer.variant,company:offer.company,price:{amountCents:offer.priceCents,currency:offer.currency},condition:offer.condition,warranty:offer.warranty,returns:offer.returns,availability:offer.available,provenance:{product:'COMPANY_DECLARED',availability:'LIVE_INVENTORY',verification:'ORGANIZATION_STATUS'},actions:[{type:'COMPARE_WITH_MINE',href:`/api/v1/company-network/offers/${offer.publicId}/compare-with-mine`},{type:offer.checkout.mode==='EXTERNAL'?'BUY_FROM_COMPANY':'START_STILL_CHECKOUT'}]}})}

async function augmentWanted(request,env,ctx,buyer){const base=await app.fetch(request,env,ctx),data=await base.clone().json().catch(()=>({}));if(!base.ok)return base;const list=data.wanted||data.items||[];for(const wanted of list){const pseudo={title:wanted.title||wanted.query||'',category:wanted.category||'',conditionPreference:wanted.conditionPreference||'',desiredAttributes:wanted.desiredAttributes||[],budgetMaxCents:wanted.budgetMaxCents||null};wanted.companyOffers=await commerceOptions(env,pseudo)}return json(data)}
async function augmentNow(request,env,ctx,buyer){const base=await app.fetch(request,env,ctx),data=await base.clone().json().catch(()=>({}));if(!base.ok)return base;const [orders,support,notices]=await Promise.all([env.DB.prepare(`SELECT public_id,status,payment_status,reservation_expires_at,created_at FROM company_network_orders WHERE buyer_account_id=? AND status NOT IN ('CANCELLED','EXPIRED','FULFILLED') ORDER BY created_at DESC LIMIT 20`).bind(buyer.buyer_account_id).all(),env.DB.prepare(`SELECT public_id,request_type,subject,status,updated_at FROM company_network_support_requests WHERE buyer_account_id=? AND status NOT IN ('RESOLVED','REJECTED','CANCELLED') ORDER BY updated_at DESC LIMIT 20`).bind(buyer.buyer_account_id).all(),env.DB.prepare(`SELECT n.public_id,n.title,n.severity,n.published_at,p.public_id product_public_id,op.public_id thing_public_id FROM company_network_notices n JOIN company_network_products p ON p.id=n.product_id JOIN company_network_relationships r ON r.organization_id=n.organization_id AND r.product_update_access=1 AND r.revoked_at IS NULL JOIN ownership_passports op ON op.id=r.thing_passport_id LEFT JOIN world_thing_profiles tp ON tp.passport_id=op.id WHERE r.buyer_account_id=? AND n.published_at IS NOT NULL AND (tp.gtin=p.gtin OR LOWER(op.title)=LOWER(p.name)) ORDER BY n.published_at DESC LIMIT 20`).bind(buyer.buyer_account_id).all()]);return json({...data,companyNetwork:{orders:orders.results||[],supportRequests:support.results||[],productNotices:notices.results||[]}})}

async function handle(request,env,ctx,url,buyer,company){const path=url.pathname;let m;if(path==='/api/v1/commerce/orders/demo-complete'||/\/api\/v1\/commerce\/orders\/[^/]+\/demo-complete$/.test(path))return json({error:'demo_commerce_retired',message:'Demo completion was removed. Use a real recorded checkout or external payment confirmation.'},410);if(path==='/api/v1/company-network/catalog'&&request.method==='GET')return json({offers:await publicOffers(env,{query:url.searchParams.get('q')||'',limit:url.searchParams.get('limit')||60})});if(path==='/api/v1/company-network/claims/resolve'&&request.method==='POST')return resolveClaim(request,env);if(path==='/api/v1/company-network/profile'&&company)return profile(request,env,company);if(path==='/api/v1/company-network/products'&&company)return products(request,env,company);m=path.match(/^\/api\/v1\/company-network\/products\/([^/]+)\/variants$/);if(m&&request.method==='POST'&&company){const product=await productForCompany(env,company,decodeURIComponent(m[1]));return product?addVariant(request,env,company,product):json({error:'product_not_found'},404)}if(path==='/api/v1/company-network/policies'&&company)return policies(request,env,company);if(path==='/api/v1/company-network/offers'&&company)return offers(request,env,company);if(path==='/api/v1/company-network/orders'&&request.method==='GET')return listOrders(env,buyer,company);if(path==='/api/v1/company-network/orders'&&request.method==='POST'&&buyer)return createOrder(request,env,buyer);m=path.match(/^\/api\/v1\/company-network\/orders\/([^/]+)\/confirm-external$/);if(m&&request.method==='POST'&&company)return confirmOrder(request,env,company,decodeURIComponent(m[1]));if(path==='/api/v1/company-network/claims'&&request.method==='POST'&&company)return createClaim(request,env,company);if(path==='/api/v1/company-network/claims/claim'&&request.method==='POST'&&buyer)return claimProduct(request,env,buyer);if(path==='/api/v1/company-network/relationships'&&buyer)return relationships(request,env,buyer);if(path==='/api/v1/company-network/support-requests')return supportRequests(request,env,buyer,company);if(path==='/api/v1/company-network/notices'&&company)return notices(request,env,company);m=path.match(/^\/api\/v1\/company-network\/offers\/([^/]+)\/(compare-with-mine|pre-purchase-passport)$/);if(m&&request.method==='GET'&&buyer)return m[2]==='compare-with-mine'?compareWithMine(env,buyer,decodeURIComponent(m[1])):prePurchasePassport(env,buyer,decodeURIComponent(m[1]));m=path.match(/^\/api\/v1\/world\/needs\/([^/]+)\/commerce-options$/);if(m&&request.method==='GET'&&buyer){const need=await env.DB.prepare(`SELECT * FROM world_needs WHERE buyer_account_id=? AND public_id=?`).bind(buyer.buyer_account_id,decodeURIComponent(m[1])).first();if(!need)return json({error:'need_not_found'},404);return json({needId:need.public_id,orderingRule:'OWNED_AND_NON_PURCHASE_OPTIONS_REMAIN_PRIMARY',offers:await commerceOptions(env,{...need,title:need.title,category:need.category,desiredAttributes:safeJson(need.desired_attributes_json,[]),conditionPreference:need.condition_preference,budgetMaxCents:need.budget_max_cents})})}return null}

export default{async fetch(request,env,ctx){const url=new URL(request.url),path=url.pathname,claimPage=path==='/claim',isNetwork=path.startsWith('/api/v1/company-network/')||/demo-complete$/.test(path)||/^\/api\/v1\/world\/needs\/[^/]+\/commerce-options$/.test(path),wanted=path==='/api/v1/market/wanted'&&request.method==='GET',nowRoute=path==='/api/v1/world/now'&&request.method==='GET';if(claimPage&&['GET','HEAD'].includes(request.method)){const assetUrl=new URL(request.url);assetUrl.pathname='/app.html';assetUrl.search='';return env.ASSETS.fetch(new Request(assetUrl,request))}if(!isNetwork&&!wanted&&!nowRoute)return app.fetch(request,env,ctx);try{await ensureSchema(env);const [buyer,company]=await Promise.all([buyerSession(request,env),companySession(request,env)]);const publicRoute=path==='/api/v1/company-network/catalog'||path==='/api/v1/company-network/claims/resolve'||/demo-complete$/.test(path);if(!publicRoute&&!buyer&&!company)return json({error:'unauthorized'},401);if(!['GET','HEAD'].includes(request.method)&&!sameOrigin(request))return json({error:'origin_not_allowed'},403);if(wanted){if(!buyer)return json({error:'buyer_required'},403);return augmentWanted(request,env,ctx,buyer)}if(nowRoute){if(!buyer)return app.fetch(request,env,ctx);return augmentNow(request,env,ctx,buyer)}const response=await handle(request,env,ctx,url,buyer,company);return response||app.fetch(request,env,ctx)}catch(error){log('company_network_request_failed',{path,category:clean(error?.name||'error',80),message:clean(error?.message,240)});return json({error:'company_network_unavailable'},500)}}};
